typedef int SSEventId;

struct entity;
extern "C" void sound_unpause(void *) __asm__("unpause__18SoundScriptManager");
extern "C" int sound_play(void *, SSEventId, entity *, float)
    __asm__("playEvent__18SoundScriptManager9EventTypeP6entityf");
extern "C" void sound_pause(void *) __asm__("pause__18SoundScriptManager");
extern "C" void nslFrameAdvance(float) __asm__("nslFrameAdvance__Ff");
extern void *sound_manager;
asm(".equ sound_manager,0x0046B4A0");

class SoundScriptManager {
public:
    static SoundScriptManager *inst() { return (SoundScriptManager *)sound_manager; }
    void unpause() { sound_unpause(this); }
    int playEvent(SSEventId event, entity *ent = 0, float volume = 0.0f)
    {
        return sound_play(this, event, ent, volume);
    }
    void pause()
    {
        sound_pause(this);
        nslFrameAdvance(0.1f);
    }
};

enum { SS_FE_ONX = 24 };

struct IGOFrontEnd {
    void ShowMenuBackground(bool);
};
asm(".equ ShowMenuBackground__11IGOFrontEndb,0x0017CED0");

struct FEManager {
    IGOFrontEnd *IGO;
};

struct PauseMenuVTable {
    char before_end_draw[88];
    short end_draw_adjustment;
    short end_draw_padding;
    void (*end_draw)(void *, bool);
    char before_make_active[40];
    short make_active_adjustment;
    short make_active_padding;
    void (*make_active)(void *, int, int);
};

struct PauseMenuSystem {
    char before_manager[120];
    FEManager *manager;
    char before_vtable[16];
    PauseMenuVTable *vtable;
    char before_navigation_event[32];
    int navigationEvent;

    void MakeActive(int menu, int sub_menu)
    {
        vtable->make_active((char *)this + vtable->make_active_adjustment,
                            menu, sub_menu);
    }
    void endDraw(bool unpause = true)
    {
        vtable->end_draw((char *)this + vtable->end_draw_adjustment, unpause);
    }
    enum { SaveLoadMenu = 19, SaveConfirmMenu = 20 };
};

struct SaveLoadFrontEnd {
    char before_back_menu[12964];
    int back_menu;
    int back_sub_menu;
    int forward_menu;
    int forward_sub_menu;
    enum { ACT_SAVE = 2 };
};

struct FEMenuSystem {
    char before_menus[116];
    SaveLoadFrontEnd **menus;
};

class SaveCareerPromptClass {
    char before_system[80];
public:
    FEMenuSystem *system;
private:
    char before_sys[36];
public:
    PauseMenuSystem *sys;
    enum { Yes, No };
    void Select(int entry_index);
};

void SaveCareerPromptClass::Select(int entry_index)
{
	SoundScriptManager::inst()->unpause();
	sys->navigationEvent=SoundScriptManager::inst()->playEvent(SS_FE_ONX);
	SoundScriptManager::inst()->pause();

	switch (entry_index)
	{
		case Yes:
			{
				sys->manager->IGO->ShowMenuBackground(false);
				sys->MakeActive(PauseMenuSystem::SaveLoadMenu, SaveLoadFrontEnd::ACT_SAVE);
				((SaveLoadFrontEnd *)system->menus[PauseMenuSystem::SaveLoadMenu])->forward_menu = -1;
				((SaveLoadFrontEnd *)system->menus[PauseMenuSystem::SaveLoadMenu])->forward_sub_menu = -1;
				((SaveLoadFrontEnd *)system->menus[PauseMenuSystem::SaveLoadMenu])->back_menu = PauseMenuSystem::SaveConfirmMenu;
				((SaveLoadFrontEnd *)system->menus[PauseMenuSystem::SaveLoadMenu])->back_sub_menu = -1;
			}

		break;
		case No:
			sys->endDraw(false);
		break;
	}
}
